def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # Basic validation
    if len(encoded) != len(original):
        return "Failed"

    encode_to_orig = {}
    orig_to_encode = {}

    for enc_char, orig_char in zip(encoded, original):
        # Check forwards mapping consistency
        if enc_char in encode_to_orig:
            if encode_to_orig[enc_char] != orig_char:
                return "Failed"
        else:
            encode_to_orig[enc_char] = orig_char

        # Check reverse mapping consistency
        if orig_char in orig_to_encode:
            if orig_to_encode[orig_char] != enc_char:
                return "Failed"
        else:
            orig_to_encode[orig_char] = enc_char

    # Ensure the mapping covers all 26 uppercase alphabet letters
    # If the problem domain includes only uppercase letters, we enforce length 26.
    # If mapping size is less than 26, decoding may use unmapped letters.
    if len(encode_to_orig) < 26:
        return "Failed"

    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in encode_to_orig:
            return "Failed"
        decoded_chars.append(encode_to_orig[ch])

    return ''.join(decoded_chars)

def vigenere_decrypt(key, ciphertext):
    if not key.isalpha():
        raise ValueError("Key must consist only of alphabetic characters.")
    if not ciphertext.isalpha():
        raise ValueError("Ciphertext must consist only of alphabetic characters.")
    if len(key)==0:
        raise ValueError("Key must not be empty.")
    result = []
    key_len = len(key)
    key_indices = [ord(c.lower()) - ord('a') for c in key]
    key_pos = 0
    for c in ciphertext:
        shift = key_indices[key_pos % key_len]
        if c.isupper():
            base = ord('A')
            cipher_idx = ord(c) - base
            plain_idx = (cipher_idx - shift) % 26
            result.append(chr(base + plain_idx))
        elif c.islower():
            base = ord('a')
            cipher_idx = ord(c) - base
            plain_idx = (cipher_idx - shift) % 26
            result.append(chr(base + plain_idx))
        else:
            # residual?
            result.append(c)
        key_pos += 1
    return ''.join(result)

def sort_students(student_scores):
    """
    Sorts a list of students based on their scores. The students are sorted primarily by their total score (descending),
    then by their Chinese score (descending), and finally by their student number (ascending) in case of a tie.

    Args:
    student_scores (list): A list of tuples, where each tuple consists of (student_number, total_score, Chinese_score).

    Returns:
    list: A list of tuples sorted according to the above rules.
    """
    if not isinstance(student_scores, (list, tuple)):
        raise TypeError("student_scores must be a list or tuple of tuples")
    sorted_list = []
    for idx, record in enumerate(student_scores):
        try:
            student_num, total_score, chinese_score = record
        except Exception:
            raise TypeError(f"Record at index {idx} is not a 3-element tuple")
        if not (isinstance(student_num, int) and isinstance(total_score, int) and isinstance(chinese_score, int)):
            raise TypeError(f"Record at index {idx} contains non-integer elements")
        sorted_list.append(record)
    # Perform sorting: total_score desc, chinese_score desc, student_num asc
    return sorted(sorted_list, key=lambda x: (-x[1], -x[2], x[0]))
